            else {
                // Already closed: ending the client fails any publish still waiting for its PUBACK, so it stays in the outbox.
                open.intentional = true;
                open.client.end(true);
            }
        }
        if (stopped) break;
        if (switching) continue; // New settings are tried at once; readings wait in the outbox meanwhile.
        attempt++;
        setState("retry-waiting", broker, { retryInSeconds: delay });
        await sleep(delay * 1000);
        delay = Math.min(delay * 2, broker.maxRetryDelaySeconds);
    }
}

