// Broker settings rules, the same as the .NET BrokerProfile.Validate(). Returns a problem, or null when valid.
const brokerFields = ["id", "host", "port", "useTls", "certificateLocation", "certificateSha256",
    "keepAliveSeconds", "connectTimeoutSeconds", "retryDelaySeconds", "maxRetryDelaySeconds"];
function validId(value) {
    return typeof value === "string" && value.trim() !== "" && !/[\s\/+#]/.test(value);
}
function brokerProblem(broker) {
    if (!broker || typeof broker !== "object" || Array.isArray(broker)) return "Provide a broker JSON object.";
    const unknown = Object.keys(broker).filter(key => !brokerFields.includes(key));
    if (unknown.length) return "Unknown broker field(s): " + unknown.join(", ") + ".";
    const whole = (value, min, max) => Number.isInteger(value) && value >= min && value <= max;
    if (!validId(broker.id)) return "Broker ID must be nonempty and must not contain /, +, # or whitespace.";
    if (typeof broker.host !== "string" || broker.host.trim() === "" || /\s/.test(broker.host)) return "Broker host is required and must not contain spaces.";
    if (!whole(broker.port, 1, 65535)) return "Broker port must be between 1 and 65535.";
    if (typeof broker.useTls !== "boolean") return "useTls must be true or false.";
    // Keep-alive also bounds how long a silently dead broker goes unnoticed while idle.
    if (!whole(broker.keepAliveSeconds, 5, 3600)) return "Keep-alive must be 5–3600 seconds.";
    if (!whole(broker.connectTimeoutSeconds, 1, 300)) return "Connect timeout must be 1–300 seconds.";
    if (!whole(broker.retryDelaySeconds, 1, 3600)) return "Retry delay must be 1–3600 seconds.";
    if (!Number.isInteger(broker.maxRetryDelaySeconds) || broker.maxRetryDelaySeconds < broker.retryDelaySeconds || broker.maxRetryDelaySeconds > 3600)
        return "Maximum retry delay must be at least the retry delay and at most 3600 seconds.";
    const location = broker.certificateLocation ?? null;
    const fingerprint = broker.certificateSha256 ?? null;
    if (!broker.useTls) {
        if (location !== null || fingerprint !== null) return "Certificate settings need TLS. Enable TLS or remove the certificate.";
        return null;
    }
    if (typeof location !== "string" || location.trim() === "") return "TLS needs a certificate location (file path or https URL).";
    // A drive or Unix path is a file; anything with a scheme must be https, so the trust anchor cannot be swapped in transit.
    const scheme = /^([a-z][a-z0-9+.-]*):\/\//i.exec(location)?.[1]?.toLowerCase();
    const isUrl = scheme !== undefined && scheme !== "file";
    if (isUrl && scheme !== "https") return "A certificate URL must use https.";
    if (fingerprint !== null && !/^[0-9a-f]{64}$/i.test(fingerprint)) return "Certificate fingerprint must be a SHA-256 hash: 64 hexadecimal characters.";
    if (isUrl && fingerprint === null) return "A certificate URL needs its SHA-256 fingerprint, so a replaced file is refused.";
    return null;
}
