const fromRow = row => ({
    id: row.Id, host: row.Host, port: row.Port, useTls: row.UseTls === 1,
    certificateLocation: row.CertificateLocation, certificateSha256: row.CertificateSha256,
    keepAliveSeconds: row.KeepAliveSeconds, connectTimeoutSeconds: row.ConnectTimeoutSeconds,
    retryDelaySeconds: row.RetryDelaySeconds, maxRetryDelaySeconds: row.MaxRetryDelaySeconds
});
const toParams = broker => ({
    $id: broker.id, $host: broker.host, $port: broker.port, $tls: broker.useTls ? 1 : 0,
    $location: broker.certificateLocation ?? null, $sha: broker.certificateSha256?.toLowerCase() ?? null,
    $keepAlive: broker.keepAliveSeconds, $connectTimeout: broker.connectTimeoutSeconds,
    $retry: broker.retryDelaySeconds, $maxRetry: broker.maxRetryDelaySeconds
