    if (!gateways) {
        if (method === "GET" && id === undefined)
            return reply(200, (await all("SELECT * FROM Brokers ORDER BY Id")).map(fromRow));
        if (method === "GET") {
            const row = await get("SELECT * FROM Brokers WHERE Id = $id", { $id: id });
            return row ? reply(200, fromRow(row)) : reply(404, { error: "Broker not found." });
        }
        if (method === "DELETE") {
            if (!(await get("SELECT 1 AS found FROM Brokers WHERE Id = $id", { $id: id }))) return reply(404, { error: "Broker not found." });
            if ((await get("SELECT COUNT(*) AS n FROM Brokers")).n === 1) return reply(409, { error: "The only broker cannot be deleted." });
            if (await get("SELECT 1 AS found FROM GatewayBrokers WHERE BrokerId = $id", { $id: id }))
