        if (method === "PUT" && broker.id !== id) return reply(400, { error: "Broker ID must match the URL." });
        broker.certificateSha256 = broker.certificateSha256?.toLowerCase() ?? null;
        const values = "$id, $host, $port, $tls, $location, $sha, $keepAlive, $connectTimeout, $retry, $maxRetry";
        if (method === "POST") {
