        }
        const updated = await run(`UPDATE Brokers SET Host = $host, Port = $port, UseTls = $tls, CertificateLocation = $location,
            CertificateSha256 = $sha, KeepAliveSeconds = $keepAlive, ConnectTimeoutSeconds = $connectTimeout,
            RetryDelaySeconds = $retry, MaxRetryDelaySeconds = $maxRetry WHERE Id = $id`, toParams(broker));
        return updated.changes ? reply(200, brokerRecord(broker)) : reply(404, { error: "Broker not found." });
    }

    // Which broker a gateway uses. Without an assignment it uses its own BROKER_ID setting.
    if (method === "GET")
        return reply(200, (await all("SELECT GatewayId, BrokerId FROM GatewayBrokers ORDER BY GatewayId"))
            .map(row => ({ gatewayId: row.GatewayId, brokerId: row.BrokerId })));
    if (method === "DELETE") {
        const removed = await run("DELETE FROM GatewayBrokers WHERE GatewayId = $id", { $id: id });
