    if (!validId(assignment.gatewayId) || !validId(assignment.brokerId))
        return reply(400, { error: "Gateway and broker IDs must be nonempty and must not contain /, +, # or whitespace." });
    if (assignment.gatewayId !== id) return reply(400, { error: "Gateway ID must match the URL." });
    if (!(await get("SELECT 1 AS found FROM Brokers WHERE Id = $id", { $id: assignment.brokerId })))
        return reply(400, { error: "Broker " + assignment.brokerId + " does not exist." });
    await run(`INSERT INTO GatewayBrokers (GatewayId, BrokerId) VALUES ($gateway, $broker)
        ON CONFLICT(GatewayId) DO UPDATE SET BrokerId = excluded.BrokerId`, { $gateway: id, $broker: assignment.brokerId });
    return reply(200, assignment);
} catch (error) {
    node.error(error.message, msg);
    return reply(500, { error: "Unable to access the broker registry." });
